insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('cuando-suben-los-costos-que-pasa-con-las-ganancias','negocios',array['industria']::text[],'Cuando suben los costos: ¿qué pasa con las ganancias?','Simula qué le ocurre a las ganancias de un negocio pequeño cuando suben los costos de sus insumos, y evalúa las decisiones posibles: subir precios, bajar costos o aguantar.','Simulación','~18 h',18,array['Costos','Ganancias']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'contabilidad economia administracion ingenieria industrial estadistica matematica ingenieria de sistemas finanzas analisis de sensibilidad. calculo de margenes. simulacion en hoja de calculo. toma de decisiones. hoja de calculo. un editor de graficos. datos inventados.',$a27sld${"id": "cuando-suben-los-costos-que-pasa-con-las-ganancias", "area": "negocios", "areas2": ["industria"], "titulo": "Cuando suben los costos: ¿qué pasa con las ganancias?", "resumen": "Simula qué le ocurre a las ganancias de un negocio pequeño cuando suben los costos de sus insumos, y evalúa las decisiones posibles: subir precios, bajar costos o aguantar.", "tipo": "Simulación", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Costos", "Ganancias"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Contabilidad", "Economía", "Administración", "Ingeniería Industrial", "Estadística", "Matemática", "Ingeniería de Sistemas", "Finanzas"], "problema": ["Cuando sube el precio de un insumo, el negocio se enfrenta a una decisión difícil. Si sube sus precios, puede perder clientes; si no lo hace, pierde ganancia.", "Entender cuánto afecta cada insumo ayuda a decidir qué hacer y a no reaccionar por intuición."], "desarrollar": ["Inventa un negocio con varios insumos y calcula su margen de ganancia actual. Simula tres aumentos, de cinco, diez y veinte por ciento, en el insumo principal.", "Para cada caso compara tres respuestas posibles: subir precios, cambiar de insumo o reducir la porción, y estima el efecto sobre la ganancia, sin olvidar que algunos clientes podrían irse."], "ampliaciones": [{"titulo": "Insumo más sensible", "aporta": "identifica de qué insumo depende más la ganancia."}, {"titulo": "Efecto en la demanda", "aporta": "añade cuánto bajarían las ventas si sube el precio."}, {"titulo": "Plan de contingencia", "aporta": "propón qué haría el negocio ante un aumento brusco."}], "objetivos": ["Medir el margen de ganancia.", "Simular aumentos de costos.", "Comparar respuestas posibles.", "Elegir una decisión con argumentos."], "habilidades": ["Análisis de sensibilidad.", "Cálculo de márgenes.", "Simulación en hoja de cálculo.", "Toma de decisiones."], "herramientas": ["Hoja de cálculo.", "Un editor de gráficos.", "Datos inventados."], "lineamientos": ["Usa un negocio inventado y presenta el resultado como una simulación y no como una predicción.", "Evita sugerir que bajar la calidad o la higiene sea una opción aceptable para ahorrar."], "otroSector": "El mismo análisis sirve para estudiar cómo afecta un alza de costos a un colegio, una pequeña industria o una organización."}$a27sld$::jsonb,35),
('cuanto-cobrar-por-tu-producto-o-servicio-hecho-a-mano','negocios',array['arte','sociedad']::text[],'¿Cuánto cobrar por tu producto o servicio hecho a mano?','Calcula un precio justo para algo que haces a mano, contando materiales, tiempo, gastos y ganancia, para no cobrar de menos ni de más.','Análisis','~15 h',15,array['Precios','Artesanía']::text[],array['resolver','crear']::text[],'ficticios',NULL,'economia administracion contabilidad diseno marketing ingenieria industrial comunicaciones estadistica calculo de costos. fijacion de precios. analisis de mercado. comunicacion clara. hoja de calculo. precios de materiales. precios de productos similares.',$a28sld${"id": "cuanto-cobrar-por-tu-producto-o-servicio-hecho-a-mano", "area": "negocios", "areas2": ["arte", "sociedad"], "titulo": "¿Cuánto cobrar por tu producto o servicio hecho a mano?", "resumen": "Calcula un precio justo para algo que haces a mano, contando materiales, tiempo, gastos y ganancia, para no cobrar de menos ni de más.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Precios", "Artesanía"], "intencion": ["resolver", "crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Economía", "Administración", "Contabilidad", "Diseño", "Marketing", "Ingeniería Industrial", "Comunicaciones", "Estadística"], "problema": ["Quien hace productos o servicios por su cuenta suele fijar el precio por intuición o copiando a otros, y con frecuencia no cuenta su propio tiempo. Así se cobra de menos y el trabajo no resulta sostenible.", "Un precio bien calculado ayuda a decidir, a explicar el valor al cliente y a saber si el negocio realmente deja algo."], "desarrollar": ["Elige un producto o servicio hecho a mano, real o inventado, y calcula el costo de materiales, el tiempo de trabajo con un valor por hora que definas, y gastos como transporte, empaque o publicidad.", "Suma, agrega un margen de ganancia, compara con los precios de dos alternativas del mercado y decide un precio justificando por qué."], "ampliaciones": [{"titulo": "Precio por volumen", "aporta": "calcula cómo cambia el precio si se hacen diez unidades en lugar de una."}, {"titulo": "Costo del tiempo", "aporta": "analiza qué pasa con el precio según el valor que se dé a la hora de trabajo."}, {"titulo": "Prueba con clientes", "aporta": "pregunta a cinco personas qué pagarían y compara con tu cálculo."}], "objetivos": ["Identificar todos los costos de producir.", "Valorar el tiempo propio.", "Fijar un margen razonable.", "Comparar con el mercado."], "habilidades": ["Cálculo de costos.", "Fijación de precios.", "Análisis de mercado.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Precios de materiales.", "Precios de productos similares."], "lineamientos": ["Usa precios públicos o casos inventados y no copies precios de competidores como si fueran tuyos.", "Si pruebas con clientes reales, pide su opinión sin presionarles a comprar."], "otroSector": "El mismo cálculo sirve para cobrar clases, diseño, programación o cualquier servicio que se vende por proyecto."}$a28sld$::jsonb,36),
('disena-una-estrategia-de-precios-para-un-emprendimiento','negocios',array['sociedad']::text[],'Diseña una estrategia de precios para un emprendimiento','Diseña cómo fijar y organizar los precios de un negocio, con distintas opciones como paquetes, niveles o descuentos, y evalúa cuál resulta más conveniente.','Plan','~20 h',20,array['Precios','Estrategia']::text[],array['crear','resolver']::text[],'ficticios',NULL,'marketing economia administracion contabilidad ingenieria industrial estadistica comunicaciones psicologia estrategia de precios. simulacion en hoja de calculo. analisis de escenarios. argumentacion. hoja de calculo. un editor de graficos. datos inventados.',$a29sld${"id": "disena-una-estrategia-de-precios-para-un-emprendimiento", "area": "negocios", "areas2": ["sociedad"], "titulo": "Diseña una estrategia de precios para un emprendimiento", "resumen": "Diseña cómo fijar y organizar los precios de un negocio, con distintas opciones como paquetes, niveles o descuentos, y evalúa cuál resulta más conveniente.", "tipo": "Plan", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Precios", "Estrategia"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Marketing", "Economía", "Administración", "Contabilidad", "Ingeniería Industrial", "Estadística", "Comunicaciones", "Psicología"], "problema": ["Fijar un precio no es solo sumar costos: también influye cómo se compara con la competencia, qué percibe el cliente y si hay opciones para distintos presupuestos.", "Una estrategia de precios define qué se cobra, a quién y de qué forma, y puede cambiar mucho los resultados sin cambiar el producto."], "desarrollar": ["Para un emprendimiento inventado, diseña tres estrategias de precios, por ejemplo un precio único, tres niveles de opciones o paquetes con descuento, y define el precio de cada una.", "Simula con supuestos cuántos clientes elegirían cada opción, calcula ingresos y ganancia en cada estrategia, y recomienda la más conveniente explicando los supuestos."], "ampliaciones": [{"titulo": "Precio psicológico", "aporta": "analiza cómo cambia la percepción si el precio termina en cierto número."}, {"titulo": "Precios por temporada", "aporta": "diseña precios que varíen según la época o el horario."}, {"titulo": "Prueba real", "aporta": "prueba dos precios con grupos pequeños y compara."}], "objetivos": ["Conocer estrategias de precios.", "Simular su efecto.", "Calcular ingresos y ganancias.", "Justificar una elección."], "habilidades": ["Estrategia de precios.", "Simulación en hoja de cálculo.", "Análisis de escenarios.", "Argumentación."], "herramientas": ["Hoja de cálculo.", "Un editor de gráficos.", "Datos inventados."], "lineamientos": ["Usa un caso inventado y evita estrategias engañosas: los precios deben ser claros y honestos.", "Aclara que los supuestos de demanda son estimaciones."], "otroSector": "El mismo análisis sirve para fijar la cuota de una organización, el precio de un servicio digital o tarifas de un taller."}$a29sld$::jsonb,37),
('cuanto-pagaria-un-cliente-por-un-producto-nuevo','negocios',array['sociedad']::text[],'¿Cuánto pagaría un cliente por un producto nuevo?','Diseña una pequeña encuesta para averiguar cuánto estaría dispuesta a pagar la gente por un producto nuevo, y analiza qué precio aceptaría la mayoría.','Investigación','~22 h',22,array['Precios','Encuestas']::text[],array['investigar']::text[],'propios',NULL,'marketing estadistica economia administracion psicologia comunicaciones ciencia de datos sociologia diseno de encuestas. estadistica descriptiva. interpretacion de resultados. visualizacion de datos. un formulario de encuesta. hoja de calculo. un editor de graficos.',$a30sld${"id": "cuanto-pagaria-un-cliente-por-un-producto-nuevo", "area": "negocios", "areas2": ["sociedad"], "titulo": "¿Cuánto pagaría un cliente por un producto nuevo?", "resumen": "Diseña una pequeña encuesta para averiguar cuánto estaría dispuesta a pagar la gente por un producto nuevo, y analiza qué precio aceptaría la mayoría.", "tipo": "Investigación", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Precios", "Encuestas"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Marketing", "Estadística", "Economía", "Administración", "Psicología", "Comunicaciones", "Ciencia de Datos", "Sociología"], "problema": ["Antes de lanzar un producto es difícil saber cuánto pagaría la gente. Si se pregunta directamente, muchas personas responden por cortesía o sin pensarlo, y los resultados no siempre sirven.", "Hay maneras sencillas de preguntar que dan una idea más realista, como mostrar rangos de precios o preguntar cuándo algo parece demasiado barato o demasiado caro."], "desarrollar": ["Elige un producto o servicio, real o inventado, y diseña una encuesta corta con preguntas sobre precios, como a partir de qué monto les parecería caro y a partir de cuál sospecharían de su calidad.", "Aplícala a una muestra pequeña, grafica las respuestas, identifica el rango de precios aceptable y explica cómo elegirías el precio final."], "ampliaciones": [{"titulo": "Por tipo de cliente", "aporta": "compara las respuestas por grupos, como edad o presupuesto."}, {"titulo": "Decir y hacer", "aporta": "compara lo que dicen que pagarían con lo que realmente compran en una venta de prueba."}, {"titulo": "Mejorar la encuesta", "aporta": "revisa qué preguntas confundieron y reescríbelas."}], "objetivos": ["Diseñar preguntas claras.", "Recoger respuestas de forma ética.", "Analizar rangos de precios.", "Elegir un precio con datos."], "habilidades": ["Diseño de encuestas.", "Estadística descriptiva.", "Interpretación de resultados.", "Visualización de datos."], "herramientas": ["Un formulario de encuesta.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["La encuesta debe ser anónima, voluntaria y explicar para qué se usará; no pidas datos personales.", "Reconoce que una muestra pequeña no representa a todo el mercado."], "otroSector": "El mismo método sirve para probar cuánto valoran las personas un servicio, una cuota o una entrada a un evento."}$a30sld$::jsonb,38),
('como-cambia-la-demanda-cuando-cambia-el-precio','negocios',array['ciencias','educacion']::text[],'¿Cómo cambia la demanda cuando cambia el precio?','Estudia con ejemplos cómo varía lo que se compra cuando sube o baja el precio, y por qué algunos productos son más sensibles que otros.','Simulación','~20 h',20,array['Demanda','Elasticidad']::text[],array['investigar','otro-sector']::text[],'ficticios',NULL,'economia estadistica matematica administracion ingenieria industrial ciencia de datos ingenieria de sistemas contabilidad modelado economico basico. graficos de demanda. calculo de variaciones. interpretacion de resultados. hoja de calculo. un editor de graficos. datos inventados o publicos.',$a31sld${"id": "como-cambia-la-demanda-cuando-cambia-el-precio", "area": "negocios", "areas2": ["ciencias", "educacion"], "titulo": "¿Cómo cambia la demanda cuando cambia el precio?", "resumen": "Estudia con ejemplos cómo varía lo que se compra cuando sube o baja el precio, y por qué algunos productos son más sensibles que otros.", "tipo": "Simulación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Demanda", "Elasticidad"], "intencion": ["investigar", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Economía", "Estadística", "Matemática", "Administración", "Ingeniería Industrial", "Ciencia de Datos", "Ingeniería de Sistemas", "Contabilidad"], "problema": ["En economía se sabe que, en general, si sube el precio se compra menos. Pero cuánto menos depende del producto: si es necesario o tiene sustitutos, el cambio es distinto.", "Esa sensibilidad, llamada elasticidad, explica por qué algunos negocios pueden subir precios sin perder clientes y otros no."], "desarrollar": ["Elige tres productos de distinto tipo, uno básico, uno con muchos sustitutos y uno de lujo, e inventa datos razonables de cantidad vendida a distintos precios para cada uno.", "Grafica las tres curvas de demanda, calcula cuánto cambia la cantidad ante un cambio de precio y explica por qué cada producto reacciona distinto."], "ampliaciones": [{"titulo": "Con datos reales", "aporta": "busca datos públicos de precios y consumo de un producto y analiza su reacción."}, {"titulo": "Efecto en los ingresos", "aporta": "calcula cuándo subir el precio aumenta o reduce los ingresos totales."}, {"titulo": "Un juego con el grupo", "aporta": "simula el mercado con compañeros que decidan si comprar a cada precio."}], "objetivos": ["Comprender la relación precio y cantidad.", "Graficar curvas de demanda.", "Calcular sensibilidad.", "Explicar diferencias entre productos."], "habilidades": ["Modelado económico básico.", "Gráficos de demanda.", "Cálculo de variaciones.", "Interpretación de resultados."], "herramientas": ["Hoja de cálculo.", "Un editor de gráficos.", "Datos inventados o públicos."], "lineamientos": ["Si usas datos inventados, indica que son ilustrativos; si usas datos reales, cita la fuente.", "No generalices: la sensibilidad depende del contexto y del momento."], "otroSector": "El mismo análisis sirve para estudiar cómo responde el uso de un servicio, de un transporte o de una app ante cambios de tarifa."}$a31sld$::jsonb,39),
('por-que-un-mismo-producto-cuesta-tan-distinto-en-tu-zona','negocios',array['sociedad','ciudades']::text[],'¿Por qué un mismo producto cuesta tan distinto en tu zona?','Compara el precio de los mismos productos en distintos tipos de tienda y zonas cercanas, y busca las razones de las diferencias.','Investigación','~18 h',18,array['Precios','Mercado local']::text[],array['investigar']::text[],'propios',NULL,'economia administracion estadistica sociologia geografia marketing ingenieria industrial comunicaciones observacion de datos. analisis comparativo. formulacion de hipotesis. visualizacion. hoja de calculo. cuaderno de registro de precios. un editor de graficos.',$a32sld${"id": "por-que-un-mismo-producto-cuesta-tan-distinto-en-tu-zona", "area": "negocios", "areas2": ["sociedad", "ciudades"], "titulo": "¿Por qué un mismo producto cuesta tan distinto en tu zona?", "resumen": "Compara el precio de los mismos productos en distintos tipos de tienda y zonas cercanas, y busca las razones de las diferencias.", "tipo": "Investigación", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Precios", "Mercado local"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Administración", "Estadística", "Sociología", "Geografía", "Marketing", "Ingeniería Industrial", "Comunicaciones"], "problema": ["Un mismo producto puede costar distinto en el mercado, la bodega, el supermercado o una tienda de conveniencia, y también según el barrio. Casi nadie se detiene a preguntarse por qué.", "Las diferencias dependen de costos, de la comodidad, del volumen de compra y del tipo de cliente, y entenderlas ayuda a comprar mejor y a fijar precios."], "desarrollar": ["Elige un grupo de productos básicos, anota su precio en cuatro tipos de establecimiento de tu zona durante la misma semana, y calcula el costo de una misma canasta en cada uno.", "Muestra las diferencias en una tabla y un gráfico, y propón explicaciones razonables para cada diferencia, indicando cuáles son hipótesis y cuáles se pueden comprobar."], "ampliaciones": [{"titulo": "Otra zona", "aporta": "repite el estudio en otro barrio y compara."}, {"titulo": "Costo de comodidad", "aporta": "estima cuánto más se paga por estar cerca o abierto más horas."}, {"titulo": "Cambios en el tiempo", "aporta": "repite la medición en otra semana y observa si los precios cambian."}], "objetivos": ["Recolectar precios con método.", "Comparar canastas.", "Formular hipótesis sobre las diferencias.", "Presentar resultados con claridad."], "habilidades": ["Observación de datos.", "Análisis comparativo.", "Formulación de hipótesis.", "Visualización."], "herramientas": ["Hoja de cálculo.", "Cuaderno de registro de precios.", "Un editor de gráficos."], "lineamientos": ["Anota solo precios públicos y no fotografíes a personas ni a empleados; no juzgues a un negocio como bueno o malo por su precio.", "Pide permiso si vas a anotar precios dentro de una tienda pequeña."], "otroSector": "El mismo método sirve para comparar tarifas de servicios, de transporte, de internet o de alquileres entre zonas."}$a32sld$::jsonb,40),
('por-que-elegimos-un-negocio-y-no-otro','negocios',array['sociedad']::text[],'¿Por qué elegimos un negocio y no otro?','Investiga qué factores hacen que las personas elijan una tienda o un servicio frente a otro, como precio, cercanía, confianza o trato, y cómo se ordenan según el tipo de cliente.','Investigación','~18 h',18,array['Consumidor','Decisiones']::text[],array['investigar']::text[],'propios',NULL,'marketing psicologia sociologia administracion economia comunicaciones estadistica ingenieria industrial diseno de encuestas. estadistica descriptiva. analisis de consumidor. comunicacion de hallazgos. un formulario de encuesta. hoja de calculo. un editor de graficos.',$a33sld${"id": "por-que-elegimos-un-negocio-y-no-otro", "area": "negocios", "areas2": ["sociedad"], "titulo": "¿Por qué elegimos un negocio y no otro?", "resumen": "Investiga qué factores hacen que las personas elijan una tienda o un servicio frente a otro, como precio, cercanía, confianza o trato, y cómo se ordenan según el tipo de cliente.", "tipo": "Investigación", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Consumidor", "Decisiones"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Marketing", "Psicología", "Sociología", "Administración", "Economía", "Comunicaciones", "Estadística", "Ingeniería Industrial"], "problema": ["Dos negocios similares pueden tener resultados muy distintos. A veces gana el más barato, otras el más cercano, el más confiable o el que atiende mejor.", "Saber qué pesa más en la decisión de compra ayuda a un negocio a enfocar sus esfuerzos en lo que realmente importa a sus clientes."], "desarrollar": ["Elige un tipo de negocio de tu zona, como una bodega, una librería o una cafetería, y arma una encuesta anónima corta pidiendo que ordenen por importancia factores como precio, cercanía, variedad, atención y limpieza.", "Analiza los resultados por grupos, identifica los factores que más pesan y propón tres acciones que un negocio podría tomar con esa información."], "ampliaciones": [{"titulo": "Por qué se deja de ir", "aporta": "investiga qué razones llevan a dejar de comprar en un lugar."}, {"titulo": "Lo que no se dice", "aporta": "compara lo que las personas dicen que valoran con lo que realmente hacen."}, {"titulo": "Decisión de grupo", "aporta": "analiza si la elección cambia cuando se compra en compañía."}], "objetivos": ["Diseñar una encuesta sobre decisiones de compra.", "Ordenar factores por importancia.", "Analizar por grupos.", "Proponer acciones concretas."], "habilidades": ["Diseño de encuestas.", "Estadística descriptiva.", "Análisis de consumidor.", "Comunicación de hallazgos."], "herramientas": ["Un formulario de encuesta.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["La encuesta debe ser anónima y voluntaria; no preguntes por datos personales ni nombres de negocios concretos para criticarlos.", "Presenta los resultados como tendencias de una muestra pequeña."], "otroSector": "El mismo estudio sirve para entender por qué se elige una aplicación, una universidad o un medio de transporte."}$a33sld$::jsonb,41),
('competencia-local-que-hace-distinta-a-una-marca','negocios',array['sociedad','arte']::text[],'Competencia local: ¿qué hace distinta a una marca?','Compara dos o tres negocios del mismo rubro en tu zona y descubre qué los diferencia en oferta, imagen, trato y precio, y qué espacio queda libre para un nuevo competidor.','Análisis','~18 h',18,array['Competencia','Marca']::text[],array['investigar']::text[],'propios',NULL,'marketing administracion diseno comunicaciones economia sociologia psicologia publicidad analisis competitivo. observacion sistematica. sintesis de informacion. pensamiento creativo. una tabla comparativa. cuaderno de observacion. un editor de presentaciones.',$a34sld${"id": "competencia-local-que-hace-distinta-a-una-marca", "area": "negocios", "areas2": ["sociedad", "arte"], "titulo": "Competencia local: ¿qué hace distinta a una marca?", "resumen": "Compara dos o tres negocios del mismo rubro en tu zona y descubre qué los diferencia en oferta, imagen, trato y precio, y qué espacio queda libre para un nuevo competidor.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Competencia", "Marca"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Marketing", "Administración", "Diseño", "Comunicaciones", "Economía", "Sociología", "Psicología", "Publicidad"], "problema": ["En una misma calle hay varios negocios que venden casi lo mismo. Algunos se ven iguales y compiten solo por precio; otros logran una identidad que los hace reconocibles.", "Analizar a la competencia sin copiarla permite entender qué valoran los clientes y dónde hay oportunidades que nadie está cubriendo."], "desarrollar": ["Elige un rubro, como cafeterías o librerías, y observa desde fuera tres negocios cercanos: qué ofrecen, cómo se presentan, qué precios muestran, cómo atienden y qué público parece frecuentarlos.", "Arma una tabla comparativa, identifica qué hace distinto a cada uno y propón un posicionamiento posible para un negocio nuevo que no repita lo mismo."], "ampliaciones": [{"titulo": "Mapa de posicionamiento", "aporta": "ubica a los negocios en un mapa de precio frente a calidad percibida."}, {"titulo": "Voz de los clientes", "aporta": "pregunta a cinco clientes por qué prefieren cada lugar."}, {"titulo": "Marca propia", "aporta": "diseña el nombre y el mensaje de un negocio nuevo del rubro."}], "objetivos": ["Observar a la competencia con criterio.", "Comparar atributos de forma ordenada.", "Identificar oportunidades.", "Proponer un posicionamiento."], "habilidades": ["Análisis competitivo.", "Observación sistemática.", "Síntesis de información.", "Pensamiento creativo."], "herramientas": ["Una tabla comparativa.", "Cuaderno de observación.", "Un editor de presentaciones."], "lineamientos": ["Observa solo lo público, sin ingresar a zonas privadas ni pedir información confidencial, y evita críticas personales a los dueños.", "Presenta tus conclusiones como una lectura externa y no como un juicio sobre la calidad de los negocios."], "otroSector": "El mismo análisis sirve para comparar aplicaciones, universidades, clubes o servicios públicos de un mismo tipo."}$a34sld$::jsonb,42),
('marketing-de-bajo-costo-para-un-negocio-pequeno','negocios',array['tecnologia','sociedad']::text[],'Marketing de bajo costo para un negocio pequeño','Diseña un conjunto de acciones de marketing que un negocio pequeño pueda hacer con muy poco dinero, como redes, recomendaciones, alianzas locales y buena presencia.','Plan','~20 h',20,array['Marketing','Bajo costo']::text[],array['crear','resolver']::text[],'ficticios',NULL,'marketing comunicaciones publicidad administracion diseno ingenieria de sistemas economia psicologia planificacion de marketing. estimacion de costo y retorno. redaccion de mensajes. medicion basica. hoja de calculo. un editor de diseno sencillo. redes sociales de ejemplo.',$a35sld${"id": "marketing-de-bajo-costo-para-un-negocio-pequeno", "area": "negocios", "areas2": ["tecnologia", "sociedad"], "titulo": "Marketing de bajo costo para un negocio pequeño", "resumen": "Diseña un conjunto de acciones de marketing que un negocio pequeño pueda hacer con muy poco dinero, como redes, recomendaciones, alianzas locales y buena presencia.", "tipo": "Plan", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Marketing", "Bajo costo"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Marketing", "Comunicaciones", "Publicidad", "Administración", "Diseño", "Ingeniería de Sistemas", "Economía", "Psicología"], "problema": ["Un negocio pequeño no puede gastar como una gran marca, pero tampoco necesita hacerlo para ser visto. Hay acciones baratas o gratuitas que funcionan si se eligen bien y se hacen con constancia.", "El problema es que muchos prueban un poco de todo sin medir nada, y no saben qué les trajo clientes."], "desarrollar": ["Inventa un negocio pequeño y propón cinco acciones de bajo costo, como una cuenta en redes con contenido útil, un sistema de recomendados, una alianza con un negocio vecino o un buen letrero.", "Para cada acción estima costo, esfuerzo y resultado esperado, elige las dos más convenientes y define cómo medirías si funcionan."], "ampliaciones": [{"titulo": "Calendario de un mes", "aporta": "arma un calendario de acciones y contenidos para un mes."}, {"titulo": "Medir sin gastar", "aporta": "diseña una forma simple de saber de dónde vino cada cliente."}, {"titulo": "Comparar con pagar anuncios", "aporta": "compara el costo por cliente de estas acciones con el de una publicidad pagada."}], "objetivos": ["Conocer acciones de marketing accesibles.", "Estimar costo y resultado.", "Priorizar con criterio.", "Definir cómo medir resultados."], "habilidades": ["Planificación de marketing.", "Estimación de costo y retorno.", "Redacción de mensajes.", "Medición básica."], "herramientas": ["Hoja de cálculo.", "Un editor de diseño sencillo.", "Redes sociales de ejemplo."], "lineamientos": ["Trabaja con un negocio inventado o uno tuyo; no publiques sobre un negocio real sin permiso ni uses imágenes de terceros.", "No prometas resultados ni uses mensajes engañosos."], "otroSector": "El mismo plan sirve para difundir un evento, un club, un proyecto social o un portafolio personal."}$a35sld$::jsonb,43),
('plan-de-marketing-y-lanzamiento-con-presupuesto-limitado','negocios',array['sociedad']::text[],'Plan de marketing y lanzamiento con presupuesto limitado','Arma el plan completo para lanzar un producto o servicio con presupuesto limitado: objetivos, público, mensaje, canales, calendario y cómo medir si funcionó.','Plan','3 a 5 semanas',25,array['Lanzamiento','Plan de marketing']::text[],array['crear']::text[],'ficticios',NULL,'marketing administracion comunicaciones publicidad economia diseno contabilidad ingenieria industrial planificacion estrategica. gestion de presupuesto. programacion de actividades. presentacion de planes. hoja de calculo. un editor de presentaciones. un calendario.',$a36sld${"id": "plan-de-marketing-y-lanzamiento-con-presupuesto-limitado", "area": "negocios", "areas2": ["sociedad"], "titulo": "Plan de marketing y lanzamiento con presupuesto limitado", "resumen": "Arma el plan completo para lanzar un producto o servicio con presupuesto limitado: objetivos, público, mensaje, canales, calendario y cómo medir si funcionó.", "tipo": "Plan", "tiempo": "3 a 5 semanas", "horas": 25, "etiquetas": ["Lanzamiento", "Plan de marketing"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Marketing", "Administración", "Comunicaciones", "Publicidad", "Economía", "Diseño", "Contabilidad", "Ingeniería Industrial"], "problema": ["Lanzar algo sin plan suele dar mucho ruido y pocos clientes. Un lanzamiento necesita saber a quién se dirige, qué se quiere lograr, cuándo y con qué recursos.", "Con presupuesto limitado, cada decisión cuenta, y es importante priorizar lo que sí mueve las ventas."], "desarrollar": ["Elige un producto o servicio inventado y redacta un plan con objetivos medibles, público, mensaje central, canales elegidos, presupuesto repartido, calendario de actividades y responsables.", "Define indicadores, como consultas o ventas, y una reunión de revisión a mitad del plan donde se decida qué ajustar según lo observado."], "ampliaciones": [{"titulo": "Antes, durante y después", "aporta": "divide el plan en etapas con acciones para cada una."}, {"titulo": "Plan B", "aporta": "prepara qué se haría si los primeros resultados son menores a lo esperado."}, {"titulo": "Presentación del plan", "aporta": "prepara una presentación corta para convencer a un inversionista ficticio."}], "objetivos": ["Definir objetivos medibles.", "Repartir un presupuesto limitado.", "Programar actividades.", "Establecer indicadores y revisión."], "habilidades": ["Planificación estratégica.", "Gestión de presupuesto.", "Programación de actividades.", "Presentación de planes."], "herramientas": ["Hoja de cálculo.", "Un editor de presentaciones.", "Un calendario."], "lineamientos": ["Trabaja con un producto inventado y presupuestos de referencia, y no prometas resultados reales de ventas.", "Evita usar datos personales para segmentar de forma invasiva."], "otroSector": "El mismo plan sirve para lanzar una campaña social, un evento académico o un emprendimiento digital."}$a36sld$::jsonb,44),
('que-promocion-o-publicidad-atrae-mas-clientes-con-el-mismo-presu','negocios',array['sociedad']::text[],'¿Qué promoción o publicidad atrae más clientes con el mismo presupuesto?','Compara con un caso inventado qué conviene más con un mismo presupuesto: un descuento, un anuncio, un regalo o una recomendación, midiendo cuántos clientes y cuánta ganancia trae cada una.','Simulación','~22 h',22,array['Publicidad','Promociones']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'marketing estadistica publicidad administracion economia ciencia de datos comunicaciones contabilidad analisis de marketing. simulacion en hoja de calculo. diseno de pruebas. interpretacion de resultados. hoja de calculo. un editor de graficos. datos inventados.',$a37sld${"id": "que-promocion-o-publicidad-atrae-mas-clientes-con-el-mismo-presu", "area": "negocios", "areas2": ["sociedad"], "titulo": "¿Qué promoción o publicidad atrae más clientes con el mismo presupuesto?", "resumen": "Compara con un caso inventado qué conviene más con un mismo presupuesto: un descuento, un anuncio, un regalo o una recomendación, midiendo cuántos clientes y cuánta ganancia trae cada una.", "tipo": "Simulación", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Publicidad", "Promociones"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Marketing", "Estadística", "Publicidad", "Administración", "Economía", "Ciencia de Datos", "Comunicaciones", "Contabilidad"], "problema": ["Un negocio con un presupuesto pequeño debe elegir entre varias formas de atraer clientes. No todas rinden igual, y muchas se eligen por costumbre y no por resultados.", "Comparar por costo por cliente nuevo y por ganancia final permite decidir mejor y probar con poco riesgo."], "desarrollar": ["Inventa un negocio con un presupuesto fijo de promoción y propón cuatro opciones, con supuestos razonables de alcance, tasa de respuesta y compra.", "Calcula para cada opción el número de clientes, el costo por cliente y la ganancia, compara y explica qué supuestos cambian el resultado."], "ampliaciones": [{"titulo": "Prueba A/B", "aporta": "diseña una prueba para comparar dos mensajes con un grupo pequeño."}, {"titulo": "Efecto a largo plazo", "aporta": "analiza qué opción trae clientes que regresan."}, {"titulo": "Combinaciones", "aporta": "evalúa si combinar dos acciones rinde más que una sola."}], "objetivos": ["Comparar opciones con el mismo presupuesto.", "Calcular costo por cliente.", "Analizar la sensibilidad a los supuestos.", "Elegir con argumentos."], "habilidades": ["Análisis de marketing.", "Simulación en hoja de cálculo.", "Diseño de pruebas.", "Interpretación de resultados."], "herramientas": ["Hoja de cálculo.", "Un editor de gráficos.", "Datos inventados."], "lineamientos": ["Usa supuestos inventados y no los presentes como resultados reales de campañas.", "Si haces una prueba con personas, que sea voluntaria y sin recoger datos personales."], "otroSector": "El mismo método sirve para comparar formas de invitar a un evento, de convocar voluntarios o de difundir un proyecto."}$a37sld$::jsonb,45),
('cuanto-cuesta-conseguir-un-nuevo-cliente','negocios',array['sociedad']::text[],'¿Cuánto cuesta conseguir un nuevo cliente?','Calcula cuánto invierte un negocio, en publicidad, tiempo y descuentos, para conseguir un cliente nuevo, y compáralo con lo que ese cliente deja en ganancia.','Análisis','~18 h',18,array['Clientes','Costo de adquisición']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'marketing administracion economia contabilidad estadistica ciencia de datos ingenieria industrial ingenieria de sistemas analisis de costos. calculo de indicadores. interpretacion financiera. comunicacion clara. hoja de calculo. un editor de graficos. datos inventados.',$a38sld${"id": "cuanto-cuesta-conseguir-un-nuevo-cliente", "area": "negocios", "areas2": ["sociedad"], "titulo": "¿Cuánto cuesta conseguir un nuevo cliente?", "resumen": "Calcula cuánto invierte un negocio, en publicidad, tiempo y descuentos, para conseguir un cliente nuevo, y compáralo con lo que ese cliente deja en ganancia.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Clientes", "Costo de adquisición"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Marketing", "Administración", "Economía", "Contabilidad", "Estadística", "Ciencia de Datos", "Ingeniería Industrial", "Ingeniería de Sistemas"], "problema": ["Atraer un cliente cuesta dinero y tiempo, pero casi nunca se calcula. Un negocio puede estar gastando más en conseguir clientes de lo que esos clientes le dejan.", "Conocer ese costo permite decidir cuánto invertir en publicidad y cuáles clientes convienen más."], "desarrollar": ["Inventa un negocio y suma todo lo que gasta en conseguir clientes en un mes, incluidos anuncios, descuentos de bienvenida y horas de trabajo, y divídelo entre los clientes nuevos que llegaron.", "Compara ese costo con la ganancia que deja un cliente promedio durante varios meses, y concluye si el negocio está ganando o perdiendo por cada cliente nuevo."], "ampliaciones": [{"titulo": "Por canal", "aporta": "calcula el costo por cliente en cada canal de captación."}, {"titulo": "Clientes que se quedan", "aporta": "incluye cuánto tiempo permanece un cliente y cuánto deja en total."}, {"titulo": "Meta de crecimiento", "aporta": "calcula cuánto se podría invertir para crecer sin perder dinero."}], "objetivos": ["Identificar los costos de captar clientes.", "Calcular el costo por cliente.", "Compararlo con la ganancia que deja.", "Tomar decisiones de inversión."], "habilidades": ["Análisis de costos.", "Cálculo de indicadores.", "Interpretación financiera.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Un editor de gráficos.", "Datos inventados."], "lineamientos": ["Usa un negocio inventado y aclara que son supuestos; no uses datos reales de clientes.", "El resultado es un ejercicio de aprendizaje y no una asesoría de inversión."], "otroSector": "El mismo cálculo sirve para evaluar el costo de captar voluntarios, usuarios de una aplicación o estudiantes de un curso."}$a38sld$::jsonb,46)
